33	 *     (i.e., more voters prefer them over each opponent than vice versa).
34	 *
35	 * Result:
36	 *   - If such a candidate exists, they are declared the winner.
37	 *   - If no candidate beats all others (due to cycles, e.g., A beats B, B beats C, C beats A), 
38	 *     there is no Condorcet winner.
39	 */
40	function findCondorcetWinner(ballots, candidateNames) {
41	  const matrix = buildPairwiseMatrix(ballots, candidateNames);
42	  const n = candidateNames.length;
43	  
44	  // Calculate win count for each candidate (number of head-to-head victories)
45	  const winCounts = [];
