47	    let wins = 0;
48	    for (let j = 0; j < n; j++) {
49	      if (i !== j && matrix[i][j] > matrix[j][i]) {
50	        wins++;
51	      }
52	    }
53	    winCounts.push({ candidate: candidateNames[i], score: wins });
54	  }
55	  
56	  // Sort by win count (descending)
57	  const rankedCandidates = winCounts.sort((a, b) => b.score - a.score);
58	  
59	  // Check for Condorcet winner
60	  for (let i = 0; i < n; i++) {
61	    let isWinner = true;
62	    for (let j = 0; j < n; j++) {
63	      if (i !== j && matrix[i][j] <= matrix[j][i]) {
64	        isWinner = false;
65	        break;
66	      }
67	    }
